import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"偏见与毒性基准","description":"","frontmatter":{"title":"偏见与毒性基准","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bias-toxicity-benchmarks.md","filePath":"llm/bias-toxicity-benchmarks.md","lastUpdated":1789023840000}'),c={name:"llm/bias-toxicity-benchmarks.md"};function p(B,a,E,A,_,P){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="偏见与毒性基准" tabindex="-1">偏见与毒性基准 <a class="header-anchor" href="#偏见与毒性基准" aria-label="Permalink to &quot;偏见与毒性基准&quot;">​</a></h1><div class="epigraph"><p>毒性分数测的是分类器眼中的冒犯密度；偏见基准测的是刻板关联。两者都不是公平的完整定义，更不是红队的替代。</p><footer>—— Gehman 等 RealToxicityPrompts；Parrish 等 BBQ；Dhamala 等 BOLD</footer></div><p><a href="/llm/red-team-eval">上一课</a>覆盖对抗性突破。分布性伤害需要另一套仪器：在固定提示集上测刻板续写、毒性与 QA 偏见。本课写这些基准怎么读。缺口是不要用 Perspective 式分数签发「已对齐」。后课能力引出回到上限；本课先钉住平均行为。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gehman 的 RealToxicityPrompts 用有毒前缀测续写毒性，依赖外部毒性分类器，分类器自身有偏见与域偏移。BOLD、CrowS-Pairs、StereoSet 测关联与填空偏好，题面英语中心、模板脆弱。Parrish 的 BBQ 把偏见做成有上下文与无上下文的 QA，能区分「不知道」与「靠刻板猜」。选错仪器会把拒答一切敏感话题当成偏见胜利。</p><p>这些基准公开已久，易污染，也易被「对这套模板过拒」刷高。它们适合回归与切片诊断（按群体、按题型），不适合当唯一公平声明。</p><p><span class="marginnote">毒性分类器把身份词当风险特征时，关于受歧视群体的正当讨论会被标毒。必须人工抽检假阳性，不能把分类器均值写进模型卡当无害证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分列：毒性续写（分类器 + 人抽检）、刻板 QA（BBQ 一类）、职业/性别关联、拒答切片。固定解码温度。报告按群体切片，禁止只报总均值——均值会让受害切片与过拒切片对冲。与产品语言一致：中文产品要有中文毒性与偏见样本，不能只跑英文 RealToxicityPrompts。</p>',9)),(e(),n(m,null,{default:r(()=>[h(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E5%9B%BA%E5%AE%9A%E6%8F%90%E7%A4%BA%E9%9B%86%22%5D%20--%3E%20TOX%5B%22%E6%AF%92%E6%80%A7%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20PR%20--%3E%20ST%5B%22%E5%88%BB%E6%9D%BF%20QA%20%2F%20%E5%A1%AB%E7%A9%BA%22%5D%0A%20%20TOX%20--%3E%20SLICE%5B%22%E7%BE%A4%E4%BD%93%E5%88%87%E7%89%87%22%5D%0A%20%20ST%20--%3E%20SLICE%0A%20%20SLICE%20--%3E%20HUM%5B%22%E4%BA%BA%E6%8A%BD%E6%A3%80%E5%81%87%E9%98%B3%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>语言模型复制语料里的共现。基准把共现写成可计数的选择或续写。降低分数的路径有三条：改数据、改对齐拒答、改解码。前两条改模型，后一条改评测时的表面。只在评测时加过滤，卡上的数会好看、产品关掉过滤就回去。必须声明评测是否含过滤器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准不覆盖交叉身份、也不覆盖部署语境下的权力关系。法律合规另走审计。下一课能力引出：对危险与偏见任务，默认提示可能低估模型实际上限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>毒性与偏见基准是分布回归，按切片读，不单报均值。</li><li>分类器假阳性要人抽检；过拒不是公平。</li><li>评测是否含过滤器必须声明。</li><li>出处：Gehman 等 RealToxicityPrompts；Parrish 等 BBQ；Dhamala 等 BOLD；CrowS-Pairs / StereoSet。</li></ul>',6))])}const S=o(c,[["render",p]]);export{u as __pageData,S as default};
